 cs=cs.filter(c=>c.lesson_id!=lid);const keep=new Set(cs.map(c=>c.id));sols=sols.filter(x=>keep.has(x.course_id));fls=fls.filter(x=>keep.has(x.course_id));qzs=qzs.filter(x=>keep.has(x.course_id));
