function cfAsk(){return new Promise(res=>{const K=typeof TURNSTILE_SITEKEY==='string'?TURNSTILE_SITEKEY:'';if(!K)return res('');
 const o=document.createElement('div');o.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);display:grid;place-items:center;z-index:9999';
 o.innerHTML='<div style="background:#fff;padding:20px;border-radius:14px;text-align:center"><p style="margin:0 0 12px;font-weight:600">تحقق أمني قبل إنشاء الحساب</p><div id="cfa"></div><button type="button" class="btn btn-o btn-s" style="margin-top:12px">إلغاء</button></div>';document.body.appendChild(o);
 const done=t=>{o.remove();res(t)};o.querySelector('button').onclick=()=>done(null);
 const go=()=>turnstile.render('#cfa',{sitekey:K,language:'ar',callback:done});
 if(window.turnstile)go();else{window.cfReady2=go;const s=document.createElement('script');s.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit&onload=cfReady2';document.head.appendChild(s)}})}
async function mkAcc(phone,pw,name){const tok=await cfAsk();if(tok===null)return 'err';const h={apikey:SUPA_KEY,'Content-Type':'application/json'};let r,j;try{r=await fetch(SUPA_URL+'/auth/v1/signup',{method:'POST',headers:h,body:JSON.stringify({email:`u${phone}@academy-users.com`,password:pw,data:{name,phone},gotrue_meta_security:tok?{captcha_token:tok}:undefined})});j=await r.json().catch(()=>({}))}catch(_){return 'err'}
 if(!r.ok)return (j.error_code||j.code)=='user_already_exists'?'exists':'err';if(!j.access_token)return 'confirm';
 await fetch(SUPA_URL+'/rest/v1/aa_edu_profiles?on_conflict=id',{method:'POST',headers:{...h,Authorization:'Bearer '+j.access_token,Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify({id:j.user.id,name,phone,grade:'prep3'})}).catch(()=>{});return 'ok'}
